inline uint64_t get_bits(uint64_t hi, uint64_t lo, int pos, int n) {
    if (n <= 0) return 0;
    if (pos + n <= 64) return (hi >> (64 - pos - n)) & low_mask(n);
    if (pos >= 64) return (lo >> (64 - (pos - 64) - n)) & low_mask(n);
    int hi_bits = 64 - pos;
    uint64_t value = (hi & low_mask(hi_bits)) << (n - hi_bits);
    value |= (lo >> (64 - (n - hi_bits))) & low_mask(n - hi_bits);
    return value;
}
